/** ATB Atlas V10 — interactive clinical learning studio, with motion preference and evidence guards. Data is educational, with unreviewed relations identified. */
const ROOT=document.getElementById('app'), ic=(name,size=18)=>`<img src="./assets/icons/${name}.svg" class="ico" width="${size}" height="${size}" aria-hidden="true" alt="">`;
const H=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es');
const storage={get(k){try{return JSON.parse(localStorage.getItem(k)||'null')}catch{return null}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}};
const CORE=['staph','strep','entero','enterobacterales','nonfermenters','anaerobes','atypicals','mycobacteria'];
const PALETTES={
  prisma:['#F05C9B','#FF8F50','#8B66D5','#4ABD86','#3B8EE6','#E9A637','#995FE5','#00ADA8','#D07154','#B07DD7','#E270AF','#8AAB3D'],
  aurora:['#E44A82','#F27F4F','#9857BE','#40B993','#4A86E9','#F2B43D','#7468E7','#22B4C4','#C87951','#9C75CC','#D976AE','#83A850'],
  tinta:['#BE3467','#CD6C30','#7255AF','#138564','#2E64B5','#C18A23','#7136C4','#168E9C','#AA563A','#9254B3','#A4487C','#64862F'],
  contraste:['#C51F62','#B9550F','#6B36C7','#047A54','#075DBD','#946300','#5227CB','#007E94','#A13B27','#6F3AAA','#9A245C','#497409']
};
const STATUS={active:{symbol:'✓',label:'Actividad habitual',text:'Relación registrada como actividad habitual; confirmar sensibilidad y contexto.',short:'Actividad',css:'is-active'},conditional:{symbol:'≈',label:'Depende del contexto',text:'La actividad puede variar por especie, fenotipo, foco o susceptibilidad.',short:'Variable',css:'is-conditional'},none:{symbol:'×',label:'Sin actividad útil',text:'La base registra ausencia de actividad clínicamente útil en ese cruce.',short:'No útil',css:'is-none'},unknown:{symbol:'·',label:'No evaluado',text:'La base no contiene evaluación: NO significa resistencia ni falta de actividad.',short:'Sin dato',css:'is-unknown'}};
const LINKS=[['mapa','grid-3x3','Mapa Micro × ATB'],['antibioticos','pill','Antibióticos'],['microorganismos','microscope','Microorganismos'],['clinica','stethoscope','Clínica'],['laboratorio','flask-conical','Laboratorio'],['comparar','columns-3','Comparar'],['aprender','graduation-cap','Aprender'],['fuentes','book-open','Fuentes']];
const FAMILY_ORDER=['Penicilinas','Cefalosporinas','Carbapenémicos','Monobactámicos','Fluoroquinolonas','Macrólidos','Tetraciclinas','Aminoglucósidos','Glicopéptidos','Oxazolidinonas'];
const FAMILY_WEIGHT=f=>{let k=FAMILY_ORDER.findIndex(s=>N(f).startsWith(N(s)));return k<0?100:k};
const GROUP_PROFILES={
 staph:['Cocos grampositivos en racimos','Piel, heridas, bacteriemia, endocarditis y dispositivos','Diferencia MSSA de MRSA: el fenotipo cambia qué betalactámicos pueden utilizarse.'],
 strep:['Cocos grampositivos en cadenas o pares','Faringitis, neumonía, meningitis, infecciones invasivas según especie','La hemólisis y el grupo/ especie orientan, pero no sustituyen susceptibilidad.'],
 entero:['Cocos grampositivos de origen intestinal','ITU, bacteriemia y endocarditis según contexto','La resistencia intrínseca a cefalosporinas hace que no todos los betalactámicos se comporten igual.'],
 'gp-rods':['Bacilos grampositivos muy heterogéneos','Infección de alimentos, tejidos, SNC o dispositivos según especie','No trates Listeria, Bacillus y Corynebacterium como si compartieran un espectro uniforme.'],
 enterobacterales:['Bacilos gramnegativos, habitualmente fermentadores','ITU, abdomen, bacteriemia y neumonía según huésped','BLEE, AmpC o CRE son mecanismos/fenotipos: cada uno cambia la interpretación.'],
 nonfermenters:['Bacilos gramnegativos no fermentadores','Infección hospitalaria, respiratoria, heridas y dispositivos','Pseudomonas, Acinetobacter y Stenotrophomonas tienen resistencias y opciones muy distintas.'],
 'gn-respiratory':['Gramnegativos con relevancia respiratoria','Sinusitis, otitis, neumonía y cuadros invasivos según especie','Identificar especie y resistencia previa ayuda a evitar coberturas innecesariamente amplias.'],
 'gn-zoonotic':['Bacterias vinculadas con reservorios o exposiciones','Historia de viaje, animales, vectores, alimentos o agua','La exposición epidemiológica puede ser más informativa que una clasificación por Gram aislada.'],
 anaerobes:['Microorganismos que crecen sin oxígeno','Abscesos, aspiración seleccionada, focos dentales e intraabdominales','El control de foco y el origen anatómico importan tanto como el antibiótico.'],
 atypicals:['Agentes con biología distinta de bacterias extracelulares típicas','Síndromes respiratorios, zoonóticos e intracelulares','La ausencia de pared en Mycoplasma explica la falta de utilidad de betalactámicos.'],
 spirochetes:['Bacterias helicoidales','Infecciones sexuales, vectoriales y sistémicas según especie','Diagnóstico, etapa clínica y tejido son determinantes; no extrapoles a toda la clase.'],
 mycobacteria:['Bacterias ácido-alcohol resistentes y afines','Tuberculosis, enfermedad pulmonar e infecciones oportunistas','Requieren identificación específica, pruebas de susceptibilidad y esquemas especializados.']
};
const QUICK=[['p-aeruginosa','Pseudomonas'],['s-aureus-mrsa','MRSA'],['e-coli-blee','E. coli BLEE'],['s-pneumoniae','Neumococo'],['b-fragilis','B. fragilis']];
let D={},X={},pal={},relMap=new Map(),byDrug=new Map(),byMicro=new Map();
const ui={route:'mapa',group:'all',drugFamily:'all',focusMicro:'all',focusDrug:'all',onlyKnown:true,status:'all',order:'family',mapStyle:'bands',allGroups:false,perPage:16,page:0,advanced:false,query:'',drugQuery:'',microQuery:'',microGroup:'all',drug:'cefepima',micro:'s-aureus-mssa',syndrome:'nac',lesson:'gram',compare:['cefepima','ceftriaxona','meropenem'],compareGroup:'all',drawer:null,modal:null,palettePreset:'prisma',selectedFocus:null,viewSaved:[],bookmark:[],showPaths:false,motionOn:storage.get('atb_v10_motion')!==false,labTab:'explorar',labMicro:'p-aeruginosa',labSyndrome:'nac',labDrugs:['cefepima','ceftriaxona','meropenem'],labStep:0,labQuery:'',quizIndex:0,quizAnswer:null,quizScore:0,quizCompleted:0,compareDragging:null};
const G=id=>D.groups.find(g=>g.id===id),A=id=>D.antibiotics.find(a=>a.id===id),P=id=>D.pathogens.find(p=>p.id===id),S=id=>D.syndromes.find(s=>s.id===id);
const rel=(a,p)=>relMap.get(a+'|'+p),drugR=id=>byDrug.get(id)||[],microR=id=>byMicro.get(id)||[];
const microIn=id=>D.pathogens.filter(p=>p.groupId===id),families=()=>[...new Set(D.antibiotics.map(a=>a.family))].sort((a,b)=>a.localeCompare(b,'es'));
const tone=id=>`style="--taxon:${H(pal[id]||'#7089bd')}"`;
const stat=r=>STATUS[r?.status]||STATUS.unknown;
const chip=(s,cls='')=>`<span class="chip ${cls}">${H(s)}</span>`;
const toRoute=type=>location.hash='#/'+type;
const route=()=>location.hash.match(/^#\/(mapa|antibioticos|microorganismos|clinica|laboratorio|comparar|aprender|fuentes)/)?.[1]||'mapa';
const statusTag=r=>`<span class="state-tag ${stat(r).css}"><b>${stat(r).symbol}</b>${stat(r).label}</span>`;
const sourceLinks=ids=>(ids||[]).map(key=>D.guides[key]?`<a class="source-link" href="${H(D.guides[key].url)}" target="_blank" rel="noopener noreferrer">${H(D.guides[key].title||key)} ${ic('arrow-up-right',13)}</a>`:'').filter(Boolean).join('')||'<span class="subtle">Fuentes de esta relación por revisar</span>';
const eList=arr=>arr.map(x=>`<li>${H(x)}</li>`).join('');
const groupBadge=id=>G(id)?`<span class="group-badge" ${tone(id)}><i></i>${H(G(id).name)}</span>`:'';
const mark=(status='unknown')=>`<span class="status-glyph ${stat({status}).css}">${stat({status}).symbol}</span>`;
function countsDrug(a){return drugR(a).reduce((x,r)=>(x[r.status]=(x[r.status]||0)+1,x),{active:0,conditional:0,none:0});}
function navigate(v){ui.drawer=null;ui.modal=null;if(route()===v){ui.route=v;render()}else toRoute(v)}
function saveView(){const obj={g:ui.group,f:ui.drugFamily,p:ui.focusMicro,a:ui.focusDrug,st:ui.status,ms:ui.mapStyle,ag:ui.allGroups,ok:ui.onlyKnown};const views=storage.get('atb_v9_views')||[];const next=[obj,...views.filter(v=>JSON.stringify(v)!==JSON.stringify(obj))].slice(0,8);storage.set('atb_v9_views',next);ui.viewSaved=next;toast('Vista guardada en este navegador')}
function restoreView(index){const v=ui.viewSaved[index];if(!v)return;ui.group=v.g;ui.drugFamily=v.f;ui.focusMicro=v.p;ui.focusDrug=v.a;ui.status=v.st;ui.mapStyle=v.ms;ui.allGroups=v.ag;ui.onlyKnown=v.ok;ui.page=0;ui.modal=null;navigate('mapa')}
function shareURL(){const q=new URLSearchParams();for(const [k,v] of [['g',ui.group],['f',ui.drugFamily],['p',ui.focusMicro],['a',ui.focusDrug],['s',ui.status],['v',ui.mapStyle]])if(v!=='all'&&v!=='bands')q.set(k,v);if(ui.allGroups)q.set('all','1');return `${location.origin}${location.pathname}#/mapa${q.size?'?'+q.toString():''}`}
function restoreHash(){const h=location.hash.split('?')[1];if(!h)return;const q=new URLSearchParams(h),valid=(k,vals)=>vals.includes(q.get(k))?q.get(k):'all';ui.group=valid('g',D.groups.map(g=>g.id));ui.drugFamily=valid('f',families());ui.focusMicro=valid('p',D.pathogens.map(p=>p.id));ui.focusDrug=valid('a',D.antibiotics.map(a=>a.id));ui.status=valid('s',['active','conditional','none','unknown']);ui.mapStyle=['bands','matrix','reverse'].includes(q.get('v'))?q.get('v'):'bands';ui.allGroups=q.get('all')==='1'}
function resetFilters(){Object.assign(ui,{group:'all',drugFamily:'all',focusMicro:'all',focusDrug:'all',status:'all',allGroups:false,onlyKnown:true,page:0,query:''});render()}
function shell(content){return `<div class="shell ${ui.motionOn?'motion-on':'motion-off'}"><aside class="rail"><button class="brand" data-action="nav:mapa"><span class="brand-icon">${ic('network',27)}</span><span><b>ATB<span>ATLAS</span></b><small>MICROBIOLOGÍA VISUAL</small></span></button><div class="rail-label">EXPLORA</div><nav class="rail-nav">${LINKS.map(([r,i,s])=>`<button class="rail-link ${ui.route===r?'on':''}" data-action="nav:${r}">${ic(i,19)}<span>${s}</span>${ui.route===r?'<i></i>':''}</button>`).join('')}</nav><div class="rail-end"><div class="rail-guide"><span>${ic('lightbulb',23)}</span><strong>Del microorganismo al antibiótico.</strong><small>Con contexto, no solo colores.</small></div><button class="rail-palette" data-action="palette">${ic('palette',18)} Personaliza los colores ${ic('chevron-right',14)}</button><button class="rail-palette motion-switch" data-action="motion" aria-pressed="${ui.motionOn}">${ic('activity',17)} ${ui.motionOn?'Animaciones activadas':'Animaciones pausadas'}</button><small>ATB Atlas · V10 · Animaciones funcionales</small></div></aside><div class="viewport"><header class="topbar"><div class="topbar-left"><button class="mobile-menu" data-action="sidebar" aria-label="Navegación">${ic('layers',20)}</button><span class="top-label">ATB ATLAS</span><span class="top-slash">/</span><b>${H(LINKS.find(x=>x[0]===ui.route)?.[2]||'Explorar')}</b></div><div class="topbar-actions"><button class="search-trigger" data-action="search">${ic('search',18)} Buscar antibiótico, microorganismo, síndrome… <kbd>⌘ K</kbd></button><button class="icon-control" title="Abrir laboratorio interactivo" aria-label="Laboratorio interactivo" data-action="nav:laboratorio">${ic('flask-conical',19)}</button><button class="icon-control" title="Colores" aria-label="Personalizar colores" data-action="palette">${ic('palette',19)}</button><button class="icon-control" title="Compartir página" aria-label="Compartir página" data-action="share">${ic('share-2',19)}</button></div></header><main id="main-content" class="main main-enter">${content}</main><footer class="footer"><span>ATB ATLAS · <b>Recurso educativo</b></span><span>Los cruces piloto requieren revisión clínica. Sin evaluar ≠ resistente.</span></footer></div>${drawer()}${modal()}${ui.mobileNav?`<div class="mobile-nav-backdrop" data-action="sidebar"><div class="mobile-nav">${LINKS.map(([r,i,s])=>`<button data-action="nav:${r}">${ic(i,19)}${s}</button>`).join('')}</div></div>`:''}</div>`}
function welcome(kicker,title,desc,extra=''){return `<div class="intro"><div><div class="kicker">${H(kicker)}</div><h1>${title}</h1><p>${H(desc)}</p></div>${extra}</div>`}
function modeNav(){return `<div class="mode-nav"><button class="mode ${ui.route==='mapa'?'on':''}" data-action="nav:mapa"><span class="mode-graphic bloom">${ic('grid-3x3',24)}</span><span><b>Micro × ATB</b><small>Mapa y cruces</small></span>${ic('arrow-right',17)}</button><button class="mode ${ui.route==='antibioticos'?'on':''}" data-action="nav:antibioticos"><span class="mode-graphic peach">${ic('pill',23)}</span><span><b>Solo ATB</b><small>Familias y fármacos</small></span>${ic('arrow-right',17)}</button><button class="mode ${ui.route==='microorganismos'?'on':''}" data-action="nav:microorganismos"><span class="mode-graphic mint">${ic('microscope',23)}</span><span><b>Solo Micro</b><small>Taxonomía y clínica</small></span>${ic('arrow-right',17)}</button></div>`}
function taxonomyHeader(groups){return `<div class="taxon-guide">${groups.map(g=>`<button class="taxon-head" ${tone(g.id)} data-action="filtergroup:${g.id}"><span class="taxon-emblem">${ic('microscope',17)}</span><b>${H(g.name)}</b><small>${microIn(g.id).length} especies/fenotipos</small></button>`).join('')}</div>`}
function guideLegend(){return `<div class="legend-key"><div><span class="legend-lead">¿Cómo se lee?</span><span class="legend-guidance">El <b>color del encabezado</b> identifica al grupo; el <b>símbolo del cruce</b> explica la actividad.</span></div><div class="legend-chips">${Object.entries(STATUS).map(([k,x])=>`<button class="legend-chip ${x.css}" data-action="legend:${k}"><strong>${x.symbol}</strong><span>${H(x.label)}<small>${k==='unknown'?'No hay datos en el atlas':k==='none'?'No es útil para este cruce':k==='conditional'?'Puede variar':'Siempre confirmar contexto'}</small></span></button>`).join('')}</div></div>`}
function guidedFilter(){const mappedD=D.antibiotics.filter(a=>drugR(a.id).length);return `<section class="filter-workspace"><div class="filter-head"><span class="label-tag">SELECTOR</span><strong>Elige por dónde empezar</strong><button class="clear-mini" data-action="clear">${ic('rotate-ccw',14)} Reiniciar</button></div><div class="focus-grid"><label><span>${ic('microscope',15)} 1 · Microorganismo</span><select id="pick-micro"><option value="all">Todos los microorganismos</option>${D.groups.map(g=>`<optgroup label="${H(g.name)}">${microIn(g.id).map(p=>`<option value="${H(p.id)}" ${ui.focusMicro===p.id?'selected':''}>${H(p.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><label><span>${ic('pill',15)} 2 · Antibiótico</span><select id="pick-drug"><option value="all">Todos los antibióticos</option>${families().map(f=>`<optgroup label="${H(f)}">${D.antibiotics.filter(a=>a.family===f).map(a=>`<option value="${H(a.id)}" ${ui.focusDrug===a.id?'selected':''}>${H(a.name)}</option>`).join('')}</optgroup>`).join('')}</select></label><label><span>${ic('chart-no-axes-gantt',15)} 3 · Vista</span><select id="pick-view"><option value="bands" ${ui.mapStyle==='bands'?'selected':''}>Mapa de grupos</option><option value="matrix" ${ui.mapStyle==='matrix'?'selected':''}>Detalle por especie</option><option value="reverse" ${ui.mapStyle==='reverse'?'selected':''}>Microorganismo → ATB</option></select></label></div><div class="quickrow"><span>Accesos rápidos</span>${QUICK.filter(([id])=>P(id)).map(([id,l])=>`<button ${tone(P(id).groupId)} class="quickchip ${ui.focusMicro===id?'on':''}" data-action="focus:${id}"><i></i>${H(l)}</button>`).join('')}<button class="text-link" data-action="advanced">${ic('sliders-horizontal',15)} Filtros avanzados ${ic(ui.advanced?'chevron-up':'chevron-down',13)}</button></div>${ui.advanced?advancedFilters():''}</section>`}
function selectOpts(id,selected,opts){return `<select id="${id}">${opts.map(([v,l])=>`<option value="${H(v)}" ${v===selected?'selected':''}>${H(l)}</option>`).join('')}</select>`}
function advancedFilters(){return `<div class="advanced"><div><b>Filtrar grupos y fármacos</b><span>Combina opciones sin perder la selección.</span></div><label>Territorio microbiano ${selectOpts('filter-group',ui.group,[['all','Todos'],...D.groups.map(g=>[g.id,g.name])])}</label><label>Familia de ATB ${selectOpts('filter-family',ui.drugFamily,[['all','Todas las familias'],...families().map(f=>[f,f])])}</label><label>Tipo de relación ${selectOpts('filter-status',ui.status,[['all','Todos los estados'],...Object.entries(STATUS).map(([k,v])=>[k,v.label])])}</label><label>Orden ${selectOpts('filter-sort',ui.order,[['family','Por familia'],['alpha','A–Z'],['relations','Más relaciones documentadas']])}</label><label class="checkbox-line"><input type="checkbox" id="only-known" ${ui.onlyKnown?'checked':''}> Mostrar inicialmente ATB con cruces registrados</label><button class="outline-action" data-action="allgroups">${ui.allGroups?'Mostrar 8 territorios clave':'Mostrar los 12 territorios'}</button></div>`}
function mapGroups(){let arr=ui.group==='all'?(ui.allGroups?D.groups:CORE.map(G).filter(Boolean)):D.groups.filter(g=>g.id===ui.group);if(ui.focusMicro!=='all')arr=arr.filter(g=>g.id===P(ui.focusMicro)?.groupId);return arr}
function mapDrugs(){let arr=D.antibiotics.filter(a=>(ui.drugFamily==='all'||a.family===ui.drugFamily)&&(ui.focusDrug==='all'||a.id===ui.focusDrug));if(ui.onlyKnown&&ui.focusDrug==='all')arr=arr.filter(a=>drugR(a.id).length);if(ui.query){const q=N(ui.query);arr=arr.filter(a=>N(a.name+' '+a.family+' '+a.subgroup).includes(q))}if(ui.status!=='all')arr=arr.filter(a=>{const ms=ui.focusMicro==='all'?(ui.group==='all'?D.pathogens:D.pathogens.filter(p=>p.groupId===ui.group)):[P(ui.focusMicro)];return ms.some(p=>stat(rel(a.id,p.id))===STATUS[ui.status])});if(ui.order==='alpha')arr.sort((a,b)=>a.name.localeCompare(b.name,'es'));else if(ui.order==='relations')arr.sort((a,b)=>drugR(b.id).length-drugR(a.id).length);else arr.sort((a,b)=>FAMILY_WEIGHT(a.family)-FAMILY_WEIGHT(b.family)||a.family.localeCompare(b.family,'es')||drugR(b.id).length-drugR(a.id).length||a.name.localeCompare(b.name,'es'));return arr}
function miniSegments(a,g){const ms=ui.focusMicro==='all'?microIn(g.id):microIn(g.id).filter(p=>p.id===ui.focusMicro);const counts={active:0,conditional:0,none:0,unknown:0};const segments=ms.map(p=>{const s=stat(rel(a.id,p.id));const k=Object.keys(STATUS).find(k=>STATUS[k]===s);counts[k]++;return `<span class="seg ${s.css}" title="${H(p.name)}: ${H(s.label)}"></span>`}).join('');return {segments,counts,total:ms.length}}
function mapBandCell(a,g){const m=miniSegments(a,g),n=m.total-m.counts.unknown;return `<button class="map-band" data-action="groupdetail:${H(a.id)}:${H(g.id)}" aria-label="${H(a.name)} y ${H(g.name)}, ${n} de ${m.total} cruces documentados" ${tone(g.id)}><span class="band-segments">${m.segments}</span><span class="band-total">${n?`${m.counts.active?'✓ '+m.counts.active+' ':''}${m.counts.conditional?'≈ '+m.counts.conditional+' ':''}${m.counts.none?'× '+m.counts.none:''}`:'Sin evaluar'} <small>${n}/${m.total}</small></span></button>`}
function mapCell(a,p){const s=stat(rel(a.id,p.id));return `<button class="map-single ${s.css}" title="${H(a.name)} × ${H(p.name)}: ${H(s.label)}" data-action="relation:${H(a.id)}:${H(p.id)}" aria-label="${H(a.name)} × ${H(p.name)}: ${H(s.label)}">${s.symbol}</button>`}
function mapTable(){const drugs=mapDrugs(),gs=mapGroups();const reverse=ui.mapStyle==='reverse';const micros=(ui.focusMicro==='all'?D.pathogens:D.pathogens.filter(p=>p.id===ui.focusMicro)).filter(p=>ui.group==='all'||p.groupId===ui.group);const totalPages=Math.ceil((reverse?micros.length:drugs.length)/ui.perPage),pages=Math.max(totalPages,1);ui.page=Math.max(0,Math.min(ui.page,pages-1));const rows=drugs.slice(ui.page*ui.perPage,(ui.page+1)*ui.perPage);let content='';if(reverse){const list=micros.slice(ui.page*ui.perPage,(ui.page+1)*ui.perPage);content=`<table class="map-table"><thead><tr><th class="sticky-col">Microorganismo</th>${drugs.slice(0,12).map(a=>`<th class="drug-col">${H(a.name)}</th>`).join('')}</tr></thead><tbody>${list.map(p=>`<tr><th class="sticky-col micro-row" ${tone(p.groupId)}><button data-action="micro:${H(p.id)}">${H(p.name)}</button><small>${H(G(p.groupId)?.name)}</small></th>${drugs.slice(0,12).map(a=>`<td>${mapCell(a,p)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}else{let last='';content=`<table class="map-table ${ui.mapStyle==='matrix'?'species-view':''}"><thead><tr><th class="sticky-col left-head">FAMILIA / ANTIBIÓTICO</th>${ui.mapStyle==='bands'?gs.map(g=>`<th ${tone(g.id)} class="group-col"><button data-action="filtergroup:${H(g.id)}"><span class="head-color"></span><b>${H(g.name)}</b><small>${miniSegments({id:''},g).total} especies y fenotipos</small></button></th>`).join(''):gs.flatMap(g=>microIn(g.id).filter(p=>ui.focusMicro==='all'||p.id===ui.focusMicro).map(p=>`<th ${tone(g.id)} class="group-col"><button data-action="micro:${H(p.id)}"><span class="head-color"></span><b>${H(p.name)}</b><small>${H(g.name)}</small></button></th>`)).join('')}</tr></thead><tbody>${rows.map(a=>{let h='';if(a.family!==last){last=a.family;h=`<tr class="family-divider"><td colspan="${(ui.mapStyle==='bands'?gs.length:gs.reduce((s,g)=>s+microIn(g.id).filter(p=>ui.focusMicro==='all'||p.id===ui.focusMicro).length,0))+1}">${H(a.family)}<small>${D.antibiotics.filter(x=>x.family===a.family).length} agentes en catálogo</small></td></tr>`}return h+`<tr><th class="sticky-col atb-name"><button data-action="drug:${H(a.id)}"><strong>${H(a.name)}</strong><small>${H(a.subgroup)}</small></button></th>${ui.mapStyle==='bands'?gs.map(g=>`<td>${mapBandCell(a,g)}</td>`).join(''):gs.flatMap(g=>microIn(g.id).filter(p=>ui.focusMicro==='all'||p.id===ui.focusMicro).map(p=>`<td>${mapCell(a,p)}</td>`)).join('')}</tr>`}).join('')}</tbody></table>`}return `<div class="map-wrap"><div class="map-canvas" id="matrix-canvas">${content}</div><div class="map-foot"><div><b>${reverse?micros.length:drugs.length}</b> ${reverse?'microorganismos':'ATB'} coinciden con tus filtros. ${ui.mapStyle==='reverse'?'Vista invertida limitada a 12 columnas: filtra por antibiótico para afinar.':'Cada segmento representa una especie/fenotipo, no un porcentaje de sensibilidad.'}</div><div class="pager"><button data-action="page:prev" ${ui.page===0?'disabled':''}>${ic('arrow-right',15)} Anterior</button><span>${ui.page+1} / ${pages}</span><button data-action="page:next" ${ui.page===pages-1?'disabled':''}>Siguiente ${ic('arrow-right',15)}</button></div></div></div>`}
function mapPage(){return `${welcome('ATLAS / MAPA INTERACTIVO','Encuentra la <em>cobertura</em> sin perderte.','Un mapa real de familias, especies y antibióticos. Primero seleccionas, después comparas y finalmente profundizas.',`<div class="intro-score"><b>111</b><span>ATB catalogados</span><b>79</b><span>Microorganismos y fenotipos</span></div>`)}${modeNav()}${guidedFilter()}<section class="atlas-panel"><div class="atlas-heading"><div><div class="kicker">TU MAPA</div><h2>${ui.focusMicro!=='all'?H(P(ui.focusMicro)?.name||'Microorganismo')+' × ATB':'Mapa de cobertura Micro × ATB'}</h2><p>Haz clic en una banda o símbolo para ver especies, contexto y fuentes.</p></div><div class="map-utilities"><button data-action="saveview">${ic('shield-check',17)} Guardar vista</button><button data-action="shareview">${ic('share-2',17)} Compartir</button><button data-action="palette">${ic('palette',17)} Colores</button></div></div>${guideLegend()}${mapTable()}</section>${ui.group!=='all'&&G(ui.group)&&GROUP_PROFILES[ui.group]?`<section class="group-learning" ${tone(ui.group)}><div class="learn-color"></div><div><span class="kicker">MICROBIOLOGÍA DEL GRUPO SELECCIONADO</span><h3>${H(G(ui.group).name)}</h3><p><b>${H(GROUP_PROFILES[ui.group][0])}.</b> ${H(GROUP_PROFILES[ui.group][1])}. ${H(GROUP_PROFILES[ui.group][2])}</p></div><button data-action="nav:microorganismos">Abrir fichas ${ic('arrow-right',15)}</button></section>`:''}<div class="below-map"><article class="study-tip"><div class="kicker">UNA REGLA QUE CAMBIA TODO</div><h3>“Actividad” no significa “es el tratamiento indicado”.</h3><p>Comprueba especie, resistencia, localización, susceptibilidad, concentraciones tisulares y guía clínica. Evita extrapolar un resultado a toda una familia.</p><button data-action="nav:aprender">${ic('book-open',16)} Entender la diferencia ${ic('arrow-right',15)}</button></article><div class="study-links"><button data-action="modal:help">${ic('circle-help',21)} <span><b>Aprende a interpretar símbolos</b><small>Ejemplos de cada estado, sin tecnicismos innecesarios</small></span>${ic('arrow-right',15)}</button><button data-action="modal:views">${ic('layers',21)} <span><b>Mis vistas guardadas</b><small>Retoma tus filtros favoritos (${ui.viewSaved.length})</small></span>${ic('arrow-right',15)}</button></div></div>`}
function catalogueFilter(which){if(which==='antibioticos'){const familiesX=families(),list=D.antibiotics.filter(a=>(ui.drugFamily==='all'||a.family===ui.drugFamily)&&N(`${a.name} ${a.family} ${a.subgroup}`).includes(N(ui.drugQuery)));const selection=A(ui.drug)||list[0];return `<div class="catalogue-layout"><aside class="catalogue-panel"><div class="catalogue-top"><b>Catálogo de antibióticos</b><span>${D.antibiotics.length} fármacos</span></div><div class="catalog-search">${ic('search',16)}<input type="search" id="drug-search" value="${H(ui.drugQuery)}" placeholder="Buscar fármaco o familia…"></div><div class="group-picker"><label>Familia farmacológica${selectOpts('catalog-family',ui.drugFamily,[['all','Todas las familias'],...familiesX.map(f=>[f,f])])}</label></div><div class="catalog-scroll">${list.slice(0,ui.perPage*3).map(a=>`<button class="catalog-entry ${selection?.id===a.id?'on':''}" data-action="drugselect:${H(a.id)}"><span class="catalog-symbol">${ic('pill',18)}</span><span><b>${H(a.name)}</b><small>${H(a.subgroup)}</small></span><i>${drugR(a.id).length||'—'}</i></button>`).join('')||`<div class="no-results">No hay coincidencias.</div>`}</div>${list.length>ui.perPage*3?`<div class="catalog-tail">Se muestran los primeros ${ui.perPage*3}. Refina por familia o búsqueda.</div>`:''}</aside><main class="entity-content">${selection?drugDetail(selection):'<div class="no-results">Selecciona un antibiótico</div>'}</main></div>`}const groups=D.groups.filter(g=>ui.microGroup==='all'||g.id===ui.microGroup),list=D.pathogens.filter(p=>(ui.microGroup==='all'||p.groupId===ui.microGroup)&&N(`${p.name} ${p.identity} ${(p.aliases||[]).join(' ')}`).includes(N(ui.microQuery)));const selection=P(ui.micro)||list[0];return `<div class="catalogue-layout"><aside class="catalogue-panel"><div class="catalogue-top"><b>Catálogo de microorganismos</b><span>${D.pathogens.length} fichas</span></div><div class="catalog-search">${ic('search',16)}<input type="search" id="micro-search" value="${H(ui.microQuery)}" placeholder="Buscar especie o fenotipo…"></div><div class="group-picker"><label>Grupo taxonómico${selectOpts('micro-group',ui.microGroup,[['all','Todos los grupos'],...D.groups.map(g=>[g.id,g.name])])}</label></div><div class="catalog-scroll">${list.slice(0,ui.perPage*3).map(p=>`<button ${tone(p.groupId)} class="catalog-entry ${selection?.id===p.id?'on':''}" data-action="microselect:${H(p.id)}"><span class="micro-symbol">${ic('microscope',17)}</span><span><b>${H(p.name)}</b><small>${H(G(p.groupId)?.name)}</small></span><i>${microR(p.id).length||'—'}</i></button>`).join('')||'<div class="no-results">No hay coincidencias.</div>'}</div>${list.length>ui.perPage*3?`<div class="catalog-tail">Se muestran los primeros ${ui.perPage*3}. Refina por grupo o búsqueda.</div>`:''}</aside><main class="entity-content">${selection?microDetail(selection):'<div class="no-results">Selecciona un microorganismo</div>'}</main></div>`}
function sourceMicro(id){const media=X.media?.[id];return media?`<figure class="micro-photo"><img src="${H(media.src)}" alt="${H(media.caption||id)}" loading="lazy"><figcaption>${H(media.caption||'Imagen microbiológica')} · <a href="${H(media.creditUrl||'#')}" target="_blank" rel="noopener noreferrer">${H(media.credit||'Fuente')}</a></figcaption></figure>`:`<div class="micro-illustration" ${tone(P(id)?.groupId)}>${ic('microscope',45)}<b>${H(G(P(id)?.groupId)?.name||'Microorganismo')}</b><small>Esquema de identidad, no microfotografía</small></div>`}
function drugDetail(a){const rs=drugR(a.id),facts=countsDrug(a.id),grouped=D.groups.map(g=>({g,items:rs.filter(r=>P(r.pathogen)?.groupId===g.id)})).filter(x=>x.items.length),guides=[...(a.referenceKeys||[])];return `<article class="identity-head drug-identity"><div class="identity-visual peach-tile">${ic('pill',47)}<small>${H(a.family)}</small></div><div><div class="kicker">FICHA ANTIBIÓTICA / ${H(a.subgroup)}</div><h2>${H(a.name)}</h2><p>${H(a.context||a.pearl||'Revisar mecanismos, espectro y limitaciones.')}</p><div class="tags">${chip(a.family,'chip-violet')}${chip(a.subgroup,'chip-peach')}${a.newer?chip('Agente reciente','chip-green'):''}</div></div><div class="identity-actions"><button data-action="drugmap:${H(a.id)}">${ic('grid-3x3',15)} Ver en el mapa</button><button data-action="addcompare:${H(a.id)}">${ic('columns-3',15)} Comparar</button></div></article><div class="fact-grid"><section class="fact-card"><div class="fact-head">${ic('circuit-board',18)} Mecanismo</div><p>${H(a.mechanism||'Mecanismo pendiente de detallar.')}</p></section><section class="fact-card"><div class="fact-head">${ic('shield-alert',18)} Punto de atención</div><p>${H(a.limitations||'Verificar función renal, susceptibilidad y foco de infección.')}</p></section><section class="fact-card"><div class="fact-head">${ic('book-open',18)} En contexto</div><p>${H(a.pearl||'Elegir tratamiento requiere datos clínicos, microbiológicos y farmacocinéticos.')}</p></section></div><div class="info-section"><div class="section-subhead"><div><h3>Espectro documentado</h3><p>${rs.length} cruces en la base piloto. No equivalen a un perfil de susceptibilidad completo.</p></div><div class="count-key">${statusTag('active')} ${facts.active} &nbsp; ${statusTag('conditional')} ${facts.conditional} &nbsp; ${statusTag('none')} ${facts.none}</div></div><div class="grouped-relations">${grouped.map(({g,items})=>`<section class="relationship-cluster" ${tone(g.id)}><header><i></i><b>${H(g.name)}</b><span>${items.length} registrado(s)</span></header><div>${items.map(r=>`<button data-action="relation:${H(a.id)}:${H(r.pathogen)}">${mark(r.status)}<span>${H(P(r.pathogen)?.name)}</span>${ic('arrow-up-right',13)}</button>`).join('')}</div></section>`).join('')||'<div class="no-results">No existen cruces registrados. Desconocido no implica resistencia.</div>'}</div></div><div class="reference-foot"><b>${ic('book-open',17)} Bibliografía vinculada</b><div>${sourceLinks(guides)}</div></div></article>`}
function microDetail(p){const g=G(p.groupId),related=(p.syndromeIds||[]).map(S).filter(Boolean),r=microR(p.id),statusCounts={active:r.filter(x=>x.status==='active').length,conditional:r.filter(x=>x.status==='conditional').length,none:r.filter(x=>x.status==='none').length};return `<article class="identity-head micro-identity" ${tone(p.groupId)}>${sourceMicro(p.id)}<div><div class="kicker">MICROBIOLOGÍA / IDENTIDAD</div><h2>${H(p.name)}</h2><p>${H(p.identity||'Ficha microbiológica en desarrollo.')}</p><div class="tags">${groupBadge(p.groupId)}${chip(p.domain||'Taxonomía','chip-violet')}${chip(p.morphology||'Morfología','chip-peach')}</div></div><div class="identity-actions"><button data-action="micromap:${H(p.id)}">${ic('grid-3x3',15)} Ver ATB asociados</button><button data-action="microcompare:${H(p.id)}">${ic('columns-3',15)} Comparar</button></div></article><div class="fact-grid"><section class="fact-card"><div class="fact-head">${ic('microscope',18)} Cómo reconocerlo</div><p>${H(p.morphology||'Morfología por caracterizar.')} · ${H(g?.domain||p.domain||'')}</p><p class="small-muted">${H(p.pearl||'La especie y su fenotipo importan para interpretar resistencia.')}</p></section><section class="fact-card"><div class="fact-head">${ic('stethoscope',18)} ¿Cuándo pensar en él?</div><p>${H(p.clinical||'El síndrome y el contexto epidemiológico orientan la sospecha.')}</p></section><section class="fact-card"><div class="fact-head">${ic('shield-alert',18)} Resistencia y contexto</div><p>Identificar la especie no demuestra un fenotipo de resistencia. Revisa cultivo, pruebas de susceptibilidad y exposición previa. No extrapoles desde otras cepas.</p></section></div><div class="info-section"><div class="section-subhead"><div><h3>Antibióticos relacionados</h3><p>Se muestran exclusivamente cruces registrados, separados por su interpretación.</p></div><div class="counts-minibar">${chip(`${statusCounts.active} habituales`,'chip-green')}${chip(`${statusCounts.conditional} variables`,'chip-gold')}${chip(`${statusCounts.none} no útiles`,'chip-rose')}</div></div><div class="relation-columns">${['active','conditional','none'].map(key=>`<section class="relation-col"><h4>${mark(key)} ${H(STATUS[key].label)}</h4>${r.filter(x=>x.status===key).map(x=>`<button data-action="relation:${H(x.antibiotic)}:${H(p.id)}"><b>${H(A(x.antibiotic)?.name)}</b><small>${H(A(x.antibiotic)?.family)}</small>${ic('arrow-up-right',13)}</button>`).join('')||'<p class="small-muted">Sin relaciones registradas.</p>'}</section>`).join('')}</div></div><div class="info-section"><div class="section-subhead"><h3>Síndromes clínicos vinculados</h3></div><div class="syndrome-pills">${related.map(s=>`<button data-action="syndrome:${H(s.id)}">${ic('stethoscope',15)} ${H(s.name)} ${ic('arrow-right',14)}</button>`).join('')||'<span class="small-muted">Aún no hay vínculos de síndrome para esta ficha.</span>'}</div></div><div class="reference-foot"><b>${ic('book-open',17)} Referencias</b><div>${sourceLinks(p.referenceKeys)}</div></div></article>`}
function drugsPage(){return `${welcome('02 / BIBLIOTECA DE FÁRMACOS','Los antibióticos, <em>por familia.</em>','Busca un fármaco, compara su mecanismo y consulta sus relaciones registradas. Una ficha, sin navegar por listas interminables.')}${modeNav()}${catalogueFilter('antibioticos')}`}
function microbesPage(){return `${welcome('03 / MICROBIOLOGÍA','De la identidad <em>a la clínica.</em>','Taxonomía, morfología, pistas diagnósticas, síndromes y antibióticos relacionados con cada patógeno.')}${modeNav()}${catalogueFilter('microorganismos')}`}
function clinicalPage(){const sites=[...new Set(D.syndromes.map(s=>s.site))].sort(),item=S(ui.syndrome)||D.syndromes[0];return `${welcome('04 / ESCENARIOS CLÍNICOS','Piensa en <em>síndromes.</em>','Partir del cuadro clínico ayuda a priorizar patógenos, evaluar resistencia y consultar la guía adecuada.') }<div class="clinical-layout"><aside class="clinical-index"><div class="index-head"><b>22 síndromes clínicos</b></div><label>Sitio anatómico${selectOpts('syndrome-site',ui.syndromeSite||'all',[['all','Todos los sitios'],...sites.map(x=>[x,x])])}</label><div class="clinical-list">${D.syndromes.filter(s=>!ui.syndromeSite||ui.syndromeSite==='all'||s.site===ui.syndromeSite).map(s=>`<button class="${item.id===s.id?'on':''}" data-action="syndrome:${H(s.id)}"><span><b>${H(s.name)}</b><small>${H(s.site)}</small></span>${ic('chevron-right',14)}</button>`).join('')}</div></aside><article class="clinical-main"><div class="kicker">SÍNDROME / ${H(item.site)}</div><h2>${H(item.name)}</h2><p class="lead">${H(item.summary)}</p><div class="clinical-flow"><div><span class="flow-step">01</span><b>Reconoce el síndrome</b><p>Identifica foco, gravedad y evolución.</p></div><div><span class="flow-step">02</span><b>Piensa en patógenos</b><p>El contexto modifica la probabilidad.</p></div><div><span class="flow-step">03</span><b>Contrasta con una guía</b><p>Valora tratamiento, sensibilidad y desescalamiento.</p></div></div><div class="clinical-two"><section><h3>${ic('list-checks',17)} Pistas que importan</h3><ul>${eList(item.clues||[])}</ul></section><section><h3>${ic('microscope',17)} Patógenos a considerar</h3><div class="clinical-organisms">${(item.pathogenIds||[]).map(id=>P(id)?`<button ${tone(P(id).groupId)} data-action="micro:${H(id)}"><i></i>${H(P(id).name)} ${ic('arrow-right',13)}</button>`:'').join('')}</div></section></div><div class="reference-foot"><b>Guías relacionadas</b><div>${sourceLinks(item.referenceKeys)}</div></div><div class="clinical-alert">La selección empírica depende de gravedad, epidemiología y factores individuales. Las relaciones de actividad del atlas no son recomendaciones automáticas de tratamiento.</div></article></div>`}
