function labDrugOptions(){const p=P(ui.labMicro)||D.pathogens[0],related=microR(p.id).map(r=>A(r.antibiotic)).filter(Boolean),rest=D.antibiotics.filter(a=>!related.some(b=>b.id===a.id));return [...related,...rest]}
function labPage(){const p=P(ui.labMicro)||D.pathogens[0],syn=S(ui.labSyndrome)||D.syndromes[0],chosen=ui.labDrugs.map(A).filter(Boolean);return `${welcome('05 / LABORATORIO INTERACTIVO','Aprende <em>haciendo.</em>','Explora cruces, ordena los fármacos, sigue un razonamiento clínico y practica con preguntas explicadas.')}
 <nav class="lab-tabs" aria-label="Modos de laboratorio"><button class="${ui.labTab==='explorar'?'on':''}" data-action="labtab:explorar">${ic('microscope',18)} 01 · Mesa de espectro</button><button class="${ui.labTab==='ruta'?'on':''}" data-action="labtab:ruta">${ic('waypoints',18)} 02 · Ruta clínica</button><button class="${ui.labTab==='reto'?'on':''}" data-action="labtab:reto">${ic('graduation-cap',18)} 03 · Reto interactivo</button></nav>
 ${ui.labTab==='explorar'?labExplorer(p,chosen):ui.labTab==='ruta'?labClinical(syn):labQuiz()}`}
function labExplorer(p,chosen){const candidates=labDrugOptions().filter(a=>N(a.name+' '+a.family).includes(N(ui.labQuery))).slice(0,10);return `<div class="lab-layout">
 <section class="lab-selector surface"><div class="lab-label">SELECCIONA UN MICROORGANISMO</div><label class="lab-select-label">Patógeno ${selectOpts('lab-micro',p.id,D.groups.flatMap(g=>microIn(g.id).map(m=>[m.id,m.name])))}</label><div class="lab-organism" ${tone(p.groupId)}><div class="lab-organism-art">${ic('microscope',30)}</div>${groupBadge(p.groupId)}<h2>${H(p.name)}</h2><p>${H(p.identity||p.clinical||'Microorganismo en el catálogo de microbiología.')}</p><button class="text-link" data-action="micro:${H(p.id)}">Abrir su ficha ${ic('arrow-up-right',14)}</button></div><div class="lab-label lab-space">BUSCA Y AÑADE ANTIBIÓTICOS</div><label class="lab-search">${ic('search',17)} <input type="search" id="lab-search" placeholder="Nombre o familia farmacológica" value="${H(ui.labQuery)}" autocomplete="off"></label><div class="lab-candidates" id="lab-candidates">${candidates.map(a=>labCandidate(a)).join('')}</div><p class="lab-hint">Arrastra a la mesa o pulsa <b>+</b>. También funciona con teclado.</p></section>
 <section class="lab-stage surface"><div class="lab-stage-head"><div><div class="lab-label">MESA DE COMPARACIÓN · ${chosen.length}/4</div><h2>Una especie. Diferentes relaciones.</h2><p>Mueve los fármacos para reorganizarlos. Selecciona una tarjeta para abrir la explicación.</p></div><button class="lab-clear" data-action="labclear">Limpiar</button></div><div class="lab-dropzone" id="lab-dropzone" aria-label="Suelta antibióticos aquí">${chosen.length?chosen.map((a,i)=>`<div class="lab-picked" data-draggable="${H(a.id)}" draggable="true"><div class="lab-pick-top"><span class="drag-grip" title="Arrastrar para reordenar">${ic('list-filter',18)}</span><span class="lab-pick-count">${String(i+1).padStart(2,'0')}</span><button data-action="labremove:${H(a.id)}" aria-label="Quitar ${H(a.name)}">${ic('x',16)}</button></div><b>${H(a.name)}</b><small>${H(a.family)} / ${H(a.subgroup||'')}</small><button class="lab-state-action" data-action="relation:${H(a.id)}:${H(p.id)}">${statusTag(rel(a.id,p.id))} ${ic('arrow-up-right',13)}</button><div class="lab-reorder"><button title="Mover a la izquierda" aria-label="Mover ${H(a.name)} hacia la izquierda" data-action="labmove:${H(a.id)}:-1" ${i===0?'disabled':''}>${ic('arrow-right',15)}</button><button title="Mover a la derecha" aria-label="Mover ${H(a.name)} hacia la derecha" data-action="labmove:${H(a.id)}:1" ${i===chosen.length-1?'disabled':''}>${ic('arrow-right',15)}</button></div></div>`).join(''):`<div class="lab-empty">${ic('pill',29)}<b>Arrastra aquí tu primer antibiótico</b><span>Máximo cuatro para comparar, sin recomendaciones automáticas.</span></div>`}</div><div class="lab-evidence"><span>${ic('shield-alert',17)}</span><p><strong>La señal visible corresponde a relaciones del corpus educativo.</strong> No confundir actividad con indicación; verificar antibiograma, foco, dosis y guías. ${p.name} tiene ${microR(p.id).length} cruces explícitos de los ${D.antibiotics.length} fármacos catalogados.</p></div>
 <div class="lab-next"><button data-action="labtomap">${ic('grid-3x3',16)} Ver la especie en el mapa</button><button data-action="labtab:ruta">Continuar a ruta clínica ${ic('arrow-right',16)}</button></div></section></div>`}
function labCandidate(a){return `<div class="lab-candidate" data-draggable="${H(a.id)}" draggable="true"><span>${ic('pill',18)} <b>${H(a.name)}</b><small>${H(a.family)}</small></span><button data-action="labadd:${H(a.id)}" aria-label="Añadir ${H(a.name)}" ${ui.labDrugs.includes(a.id)||ui.labDrugs.length>=4?'disabled':''}>${ic('arrow-right',17)}</button></div>`}
function labClinical(s){const step=ui.labStep,targets=(s.pathogenIds||[]).map(P).filter(Boolean);return `<section class="lab-clinical surface"><div class="lab-label">RECORRIDO CLÍNICO · EJEMPLO EDUCATIVO</div><div class="lab-clinical-head"><div><h2>Del síndrome a la interpretación del espectro</h2><p>Recorre las etapas en orden y elige qué información explorar.</p></div><label>Síndrome ${selectOpts('lab-syndrome',s.id,D.syndromes.map(x=>[x.id,x.name]))}</label></div><div class="lab-stepper">${['Reconoce','Prioriza patógenos','Interpreta y consulta'].map((v,i)=>`<button class="${step===i?'current':step>i?'completed':''}" data-action="labstep:${i}"><span>${i+1}</span><b>${v}</b></button>`).join('')}</div><div class="lab-stepbody" key="step${step}"><div class="lab-step-index">0${step+1} / 03</div>${step===0?`<h3>${H(s.name)}</h3><p>${H(s.summary)}</p><h4>Pistas que cambian la sospecha clínica</h4><ul>${(s.clues||[]).map(c=>`<li>${ic('info',15)} ${H(c)}</li>`).join('')}</ul>`:step===1?`<h3>Qué patógenos considerar</h3><p>El grupo no define por sí solo el tratamiento. Revisa cada patógeno antes de interpretar el mapa.</p><div class="lab-pathogens">${targets.map(p=>`<button ${tone(p.groupId)} data-action="labpickmicro:${H(p.id)}"><i></i><b>${H(p.name)}</b><small>${H(G(p.groupId)?.name)}</small>${ic('arrow-right',14)}</button>`).join('')||'<p>Esta ficha no tiene patógenos enlazados todavía.</p>'}</div>`:`<h3>De la actividad a una decisión informada</h3><p>Comprueba el antibiograma y la epidemiología local; considera el sitio de infección, gravedad, PK/PD, control de foco, alergias e interacciones. Utiliza las guías como referencia, no la cantidad de cruces de este piloto.</p><div class="lab-step-guide">${sourceLinks(s.referenceKeys)}</div><button data-action="labtomap">${ic('grid-3x3',16)} Contrastar datos en el mapa</button>`}</div><div class="lab-step-actions"><button data-action="labstep:${Math.max(0,step-1)}" ${step===0?'disabled':''}>${ic('arrow-right',15)} Anterior</button><button data-action="labstep:${Math.min(2,step+1)}" ${step===2?'disabled':''}>Siguiente etapa ${ic('arrow-right',15)}</button></div><p class="clinical-alert">Esta ruta es didáctica y no selecciona tratamiento empírico ni sustituye guías ni valoración médica.</p></section>`}
function labQuiz(){const total=LAB_QUIZ.length,index=Math.min(ui.quizIndex,total-1),q=LAB_QUIZ[index],answer=ui.quizAnswer,done=answer!==null;return `<section class="lab-quiz surface"><div class="lab-quiz-head"><div><div class="lab-label">RETO DE INTERPRETACIÓN · ${index+1}/${total}</div><h2>Comprender vale más que memorizar colores.</h2><p>Escenarios conceptuales breves. Explicación específica después de responder.</p></div><div class="lab-score"><strong>${ui.quizScore}</strong><span>aciertos</span></div></div><div class="lab-quiz-progress" aria-label="Progreso ${index+1} de ${total}"><span style="width:${((index+1)/total)*100}%"></span></div><div class="lab-question"><span class="question-topic">${H(q.focus)}</span><h3>${H(q.question)}</h3><div class="quiz-options">${q.options.map((o,i)=>`<button class="${done?(i===q.answer?'correct':i===answer?'incorrect':'muted'):''}" data-action="quizpick:${i}" ${done?'disabled':''}><span>${String.fromCharCode(65+i)}</span><b>${H(o)}</b>${done&&i===q.answer?ic('shield-check',17):''}</button>`).join('')}</div>${done?`<div class="quiz-feedback ${answer===q.answer?'right':'review'}"><b>${answer===q.answer?'Correcto.':'Revisa la interpretación.'}</b><p>${H(q.why)}</p></div><div class="quiz-continue"><button data-action="quiznext">${index===total-1?'Terminar y reiniciar':'Siguiente pregunta'} ${ic('arrow-right',15)}</button></div>`:'<p class="quiz-help">Elige una opción. No hay temporizador ni efectos que distraigan.</p>'}</div></section>`}
const extraLessons=[{id:'cuidadania',title:'La regla de las cinco preguntas',category:'RAZONAMIENTO CLÍNICO',body:'Ante una infección, separa microorganismo, foco, susceptibilidad, concentración del fármaco y necesidad de control de foco. No toda actividad in vitro se traduce en éxito clínico.',why:'Evita interpretar el mapa como un listado de tratamientos recomendados.',link:'https://www.idsociety.org/practice-guideline/amr-guidance/'},{id:'cuti25',title:'ITU complicada: del síndrome a la elección',category:'IDSA 2025',body:'La guía IDSA 2025 organiza la selección empírica según gravedad y riesgo individual. Tras obtener el cultivo y la susceptibilidad, recomienda pasar a terapia dirigida cuando sea posible.',why:'Permite distinguir antibioterapia empírica de definitiva y favorece una cobertura proporcionada.',link:'https://www.idsociety.org/practice-guideline/complicated-urinary-tract-infections/'},{id:'amr26',title:'La resistencia no es un único resultado',category:'IDSA 2026',body:'BLEE, AmpC, CRE, Pseudomonas DTR, Acinetobacter CRAB y Stenotrophomonas requieren interpretación específica. La especie, mecanismo, antibiograma y sitio de infección cambian las opciones.',why:'Una misma familia de antibióticos puede comportarse de forma diferente entre mecanismos resistentes.',link:'https://www.idsociety.org/practice-guideline/amr-guidance/'}];
function learningPage(){const items=[...extraLessons,...(X.topics||[]).map(x=>({id:'res-'+x.id,title:x.name,category:'RESISTENCIA / IDSA',body:x.explain,why:x.why,link:x.link})),...D.lessons],lesson=items.find(x=>x.id===ui.lesson)||items[0];return `${welcome('06 / APRENDER','La microbiología <em>sí se entiende.</em>','Lecciones por preguntas clínicas. Aprende primero las reglas y luego utiliza el mapa para compararlas.') }<div class="learn-layout"><aside class="learn-index"><div class="index-head">Rutas de aprendizaje</div>${items.map((l,i)=>`<button class="${l.id===lesson.id?'on':''}" data-action="lesson:${H(l.id)}"><span class="lesson-number">${String(i+1).padStart(2,'0')}</span><span><b>${H(l.title)}</b><small>${H(l.category)}</small></span>${ic('chevron-right',14)}</button>`).join('')}</aside><article class="lesson-detail"><div class="kicker">${H(lesson.category)}</div><h2>${H(lesson.title)}</h2><div class="three-step"><div>${ic('microscope',23)}<b>Reconoce</b></div><i>→</i><div>${ic('dna',23)}<b>Interpreta</b></div><i>→</i><div>${ic('pill',23)}<b>Relaciona</b></div></div><p class="lead">${H(lesson.body)}</p><section class="lesson-key"><h3>${ic('lightbulb',20)} ¿Por qué importa?</h3><p>${H(lesson.why)}</p></section><div class="reference-foot"><b>Lecturas relacionadas</b><div>${lesson.link?`<a href="${H(lesson.link)}" target="_blank" rel="noopener noreferrer" class="source-link">Ver fuente oficial ${ic('arrow-up-right',13)}</a>`:sourceLinks(lesson.refs)}</div></div><button class="lesson-map" data-action="nav:mapa">${ic('grid-3x3',16)} Ponerlo en práctica en el mapa ${ic('arrow-right',15)}</button></article></div>`}
function sourcesPage(){return `${welcome('07 / EVIDENCIA','Explora las <em>fuentes.</em>','Guías y textos vinculados al corpus actual. El inventario de referencias no implica que todos los cruces estén revisados.') }<div class="sources-grid">${Object.entries(D.guides).map(([key,s])=>`<a class="source-card" href="${H(s.url||'#')}" target="_blank" rel="noopener noreferrer"><div class="source-head">${ic('book-open',20)} <span>${H(s.category||'Referencia')} · ${H(s.year||'')}</span></div><h3>${H(s.title)}</h3><p>${H(s.topic||s.takeaway||'Referencia clínica y microbiológica')}</p><span>Consultar referencia ${ic('arrow-up-right',14)}</span></a>`).join('')}</div>`}
function drawer(){if(!ui.drawer)return '';const v=ui.drawer;let body='';if(v.type==='relation'){const a=A(v.a),p=P(v.p),r=rel(v.a,v.p);body=`<div class="kicker">ANTIBIÓTICO × MICROORGANISMO</div><h2>${H(a?.name)} <em>×</em> ${H(p?.name)}</h2>${groupBadge(p?.groupId)}<div class="drawer-state">${statusTag(r?.status||'unknown')}</div><div class="drawer-section"><h3>¿Qué significa este resultado?</h3><p>${H(r?.note||STATUS.unknown.text)}</p></div><div class="drawer-section"><h3>Qué tienes que comprobar</h3><p>${H(r?.clinical||'El foco, la susceptibilidad, la dosis, el fenotipo de resistencia y el contexto clínico pueden cambiar la utilidad del antibiótico.')}</p></div><div class="drawer-section"><h3>Fuentes registradas</h3>${sourceLinks(r?.sources||r?.referenceKeys)}</div><div class="drawer-footer"><button data-action="drug:${H(v.a)}">${ic('pill',15)} Abrir antibiótico</button><button data-action="micro:${H(v.p)}">${ic('microscope',15)} Abrir microorganismo</button></div>`}else if(v.type==='group'){const a=A(v.a),g=G(v.g),ms=ui.focusMicro==='all'?microIn(v.g):microIn(v.g).filter(p=>p.id===ui.focusMicro);body=`<div class="kicker">DESGLOSE DE GRUPO</div><h2>${H(a?.name)} <em>×</em> ${H(g?.name)}</h2>${groupBadge(g.id)}<p>Un mismo grupo incluye especies con resultados diferentes. Abre cada cruce para ver su estado individual.</p><div class="species-list">${ms.map(p=>`<button data-action="relation:${H(v.a)}:${H(p.id)}">${mark(rel(v.a,p.id)?.status||'unknown')}<span>${H(p.name)}</span>${ic('arrow-up-right',15)}</button>`).join('')}</div><p class="drawer-note">«Sin evaluar» significa que no hay una relación cargada en esta versión del atlas.</p>`}return `<div class="overlay" data-action="closedrawer"><aside class="inspector" role="dialog" aria-modal="true" aria-label="Inspector de cruce"><div class="overlay-head"><span>${ic('scan',16)} INSPECTOR</span><button aria-label="Cerrar" data-action="closedrawer">${ic('x',19)}</button></div><div class="inspector-content">${body}</div></aside></div>`}
function modal(){if(!ui.modal)return '';let body='';if(ui.modal==='search'){const q=N(ui.command||''),list=[...D.antibiotics.map(x=>({id:x.id,name:x.name,subtitle:x.family,type:'drug'})),...D.pathogens.map(x=>({id:x.id,name:x.name,subtitle:G(x.groupId)?.name||'',type:'micro'})),...D.syndromes.map(x=>({id:x.id,name:x.name,subtitle:x.site,type:'syndrome'}))].filter(x=>!q||N(x.name+' '+x.subtitle).includes(q)).slice(0,35);body=`<div class="modal-top"><div><div class="kicker">BUSCADOR GLOBAL</div><h2>¿Qué quieres encontrar?</h2></div><button data-action="closemodal">${ic('x',20)}</button></div><div class="modal-search">${ic('search',20)}<input id="global-query" type="search" placeholder="Cefepima, MRSA, meningitis…" value="${H(ui.command||'')}"></div><div class="global-results" id="global-results">${list.map(x=>`<button data-action="${x.type}:${H(x.id)}">${ic(x.type==='drug'?'pill':x.type==='micro'?'microscope':'stethoscope',17)}<span><b>${H(x.name)}</b><small>${H(x.subtitle)}</small></span>${ic('arrow-up-right',15)}</button>`).join('')||'<p>No hay coincidencias.</p>'}</div>`}else if(ui.modal==='palette'){body=`<div class="modal-top"><div><div class="kicker">SISTEMA DE COLOR</div><h2>Tu atlas, tus colores.</h2><p>Cambiar el color modifica la identidad del grupo, no el estado de actividad.</p></div><button data-action="closemodal">${ic('x',20)}</button></div><div class="preset-container"><h3>Paletas completas</h3><div class="presets">${Object.entries(PALETTES).map(([id,vals])=>`<button class="preset ${ui.palettePreset===id?'on':''}" data-action="preset:${id}"><span>${vals.slice(0,6).map(c=>`<i style="background:${c}"></i>`).join('')}</span><b>${({prisma:'Prisma',aurora:'Aurora',tinta:'Tinta',contraste:'Alto contraste'})[id]}</b></button>`).join('')}</div></div><div class="palette-grid">${D.groups.map(g=>`<label ${tone(g.id)}><i></i><span>${H(g.name)}<small id="hex-${H(g.id)}">${H(pal[g.id])}</small></span><input type="color" data-color="${H(g.id)}" value="${H(pal[g.id])}" aria-label="Color de ${H(g.name)}"></label>`).join('')}</div><div class="modal-bottom"><button data-action="preset:prisma">${ic('rotate-ccw',15)} Restaurar</button><button data-action="copycolors">${ic('copy',15)} Copiar JSON</button></div>`}else if(ui.modal==='help'){body=`<div class="modal-top"><div><div class="kicker">LEYENDA EXPLICADA</div><h2>No memorices colores: lee los símbolos.</h2></div><button data-action="closemodal">${ic('x',20)}</button></div><div class="help-walk"><div class="help-card"><b>Color del grupo</b><span class="help-group-examples">${D.groups.slice(0,4).map(g=>`<span ${tone(g.id)}>${H(g.name)}</span>`).join('')}</span><p>Indica a qué grupo pertenece el microorganismo. <strong>No indica susceptibilidad.</strong></p></div><div class="help-card"><b>Estado de la relación</b>${Object.entries(STATUS).map(([k,x])=>`<div class="help-state">${mark(k)}<span><b>${H(x.label)}</b><small>${H(x.text)}</small></span></div>`).join('')}</div><div class="help-card"><b>Cómo usarlo</b><ol><li>Elige un antibiótico o microorganismo.</li><li>Localiza su fila y grupo.</li><li>Pulsa un segmento para revisar cada especie.</li><li>Contrasta con antibiograma, foco y guías.</li></ol></div></div>`}else if(ui.modal==='views'){body=`<div class="modal-top"><div><div class="kicker">TUS ESPACIOS DE ESTUDIO</div><h2>Vistas guardadas</h2></div><button data-action="closemodal">${ic('x',20)}</button></div><div class="saved-list">${ui.viewSaved.length?ui.viewSaved.map((v,i)=>`<button data-action="restore:${i}"><span>${ic('grid-3x3',18)} Vista ${i+1}</span><small>${H(v.p!=='all'?P(v.p)?.name||v.p:'Todos los microorganismos')} · ${H(v.f==='all'?'Todas las familias':v.f)} · ${H(v.ms==='bands'?'Bandas':v.ms==='matrix'?'Especies':'Invertida')}</small>${ic('arrow-right',16)}</button>`).join(''):'<p>Aún no guardas vistas. Personaliza el mapa y usa «Guardar vista».</p>'}</div>`}else if(ui.modal==='status'){const x=STATUS[ui.modalStatus]||STATUS.unknown;body=`<div class="modal-top"><div><div class="kicker">INTERPRETACIÓN DEL ESPECTRO</div><h2>${H(x.label)}</h2></div><button data-action="closemodal">${ic('x',20)}</button></div><div class="help-state big">${mark(ui.modalStatus)}<p>${H(x.text)}</p></div><div class="clinical-alert">Estos estados describen información educativa registrada, no porcentajes de sensibilidad ni recomendaciones terapéuticas.</div>`}return `<div class="overlay" data-action="closemodal"><div class="dialog" role="dialog" aria-modal="true" aria-label="Opciones ATB Atlas">${body}</div></div>`}
function globalResultMarkup(q){const list=[...D.antibiotics.map(x=>({id:x.id,name:x.name,subtitle:x.family,type:'drug'})),...D.pathogens.map(x=>({id:x.id,name:x.name,subtitle:G(x.groupId)?.name||'',type:'micro'})),...D.syndromes.map(x=>({id:x.id,name:x.name,subtitle:x.site,type:'syndrome'}))].filter(x=>!q||N(x.name+' '+x.subtitle).includes(N(q))).slice(0,35);return list.map(x=>`<button data-action="${x.type}:${H(x.id)}">${ic(x.type==='drug'?'pill':x.type==='micro'?'microscope':'stethoscope',17)}<span><b>${H(x.name)}</b><small>${H(x.subtitle)}</small></span>${ic('arrow-up-right',15)}</button>`).join('')||'<p>No hay coincidencias.</p>'}
function render(){ui.route=route();const content=ui.route==='mapa'?mapPage():ui.route==='antibioticos'?drugsPage():ui.route==='microorganismos'?microbesPage():ui.route==='clinica'?clinicalPage():ui.route==='laboratorio'?labPage():ui.route==='comparar'?comparePage():ui.route==='aprender'?learningPage():sourcesPage();ROOT.innerHTML=shell(content)}
let toastTimer;function toast(txt){let t=document.querySelector('.toast');if(!t){t=document.createElement('div');t.className='toast';document.body.append(t)}t.textContent=txt;clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.remove(),2500)}
function takeAction(action){const [type,...parts]=action.split(':'),id=parts.join(':');if(type==='nav'){ui.mobileNav=false;return navigate(id)}if(type==='sidebar'){ui.mobileNav=!ui.mobileNav;return render()}if(type==='focus'){ui.focusMicro=id;ui.group=id==='all'?'all':P(id)?.groupId||'all';ui.page=0;return render()}if(type==='filtergroup'){ui.group=id;ui.focusMicro='all';ui.page=0;return render()}if(type==='advanced'){ui.advanced=!ui.advanced;return render()}if(type==='clear')return resetFilters();if(type==='allgroups'){ui.allGroups=!ui.allGroups;ui.page=0;return render()}if(type==='page'){ui.page+=id==='next'?1:-1;return render()}if(type==='palette'){ui.modal='palette';return render()}if(type==='legend'){ui.modal='status';ui.modalStatus=id;return render()}if(type==='search'){ui.modal='search';ui.command='';render();return document.getElementById('global-query')?.focus()}if(type==='modal'){ui.modal=id;return render()}if(type==='closedrawer'){ui.drawer=null;return render()}if(type==='closemodal'){ui.modal=null;return render()}if(type==='groupdetail'){ui.drawer={type:'group',a:parts[0],g:parts[1]};return render()}if(type==='relation'){ui.drawer={type:'relation',a:parts[0],p:parts[1]};return render()}if(type==='preset'){const colors=PALETTES[id];if(!colors)return;pal=Object.fromEntries(D.groups.map((g,i)=>[g.id,colors[i%colors.length]]));ui.palettePreset=id;storage.set('atb_palette_v9',pal);return render()}if(type==='copycolors'){navigator.clipboard?.writeText(JSON.stringify({groups:pal},null,2)).then(()=>toast('Colores copiados'));return}if(type==='drug'){ui.drug=id;ui.modal=null;ui.drawer=null;return navigate('antibioticos')}if(type==='micro'){ui.micro=id;ui.modal=null;ui.drawer=null;return navigate('microorganismos')}if(type==='syndrome'){ui.syndrome=id;ui.modal=null;ui.drawer=null;return navigate('clinica')}if(type==='drugselect'){ui.drug=id;return render()}if(type==='microselect'){ui.micro=id;return render()}if(type==='drugmap'){ui.focusDrug=id;ui.focusMicro='all';ui.page=0;return navigate('mapa')}if(type==='micromap'){ui.focusMicro=id;ui.focusDrug='all';ui.group=P(id)?.groupId||'all';ui.page=0;return navigate('mapa')}if(type==='microcompare'){ui.focusMicro=id;ui.compareGroup=P(id)?.groupId||'all';return navigate('comparar')}if(type==='addcompare'){if(!ui.compare.includes(id)){if(ui.compare.length>=4)return toast('Máximo de cuatro fármacos');ui.compare.push(id)}return navigate('comparar')}if(type==='removecompare'){ui.compare=ui.compare.filter(x=>x!==id);return render()}if(type==='lesson'){ui.lesson=id;return render()}if(type==='share'||type==='shareview'){const link=type==='shareview'?shareURL():location.href;navigator.clipboard?.writeText(link).then(()=>toast('Enlace copiado')).catch(()=>toast('Copia el enlace de la barra del navegador'));return}if(type==='motion'){ui.motionOn=!ui.motionOn;storage.set('atb_v10_motion',ui.motionOn);return render()}
 if(type==='labtab'){ui.labTab=id;return render()}
 if(type==='labadd'){if(ui.labDrugs.includes(id)||ui.labDrugs.length>=4)return;ui.labDrugs.push(id);return render()}
 if(type==='labremove'){ui.labDrugs=ui.labDrugs.filter(x=>x!==id);return render()}
 if(type==='labclear'){ui.labDrugs=[];return render()}
 if(type==='labmove'){const [drug,delta]=parts;const i=ui.labDrugs.indexOf(drug),j=i+Number(delta);if(i<0||j<0||j>=ui.labDrugs.length)return;[ui.labDrugs[i],ui.labDrugs[j]]=[ui.labDrugs[j],ui.labDrugs[i]];return render()}
 if(type==='labstep'){ui.labStep=Number(id);return render()}
 if(type==='labpickmicro'){ui.labMicro=id;ui.labTab='explorar';return render()}
 if(type==='labtomap'){ui.focusMicro=ui.labMicro;ui.group=P(ui.labMicro)?.groupId||'all';ui.focusDrug='all';ui.page=0;return navigate('mapa')}
 if(type==='quizpick'){if(ui.quizAnswer!==null)return;ui.quizAnswer=Number(id);if(ui.quizAnswer===LAB_QUIZ[ui.quizIndex].answer)ui.quizScore++;return render()}
 if(type==='quiznext'){ui.quizAnswer=null;ui.quizIndex++;if(ui.quizIndex>=LAB_QUIZ.length){const score=ui.quizScore;ui.quizIndex=0;ui.quizScore=0;toast('Reto completo: '+score+'/'+LAB_QUIZ.length+' respuestas correctas.');}return render()}
 if(type==='saveview')return saveView();if(type==='restore')return restoreView(+id)}
ROOT.addEventListener('click',e=>{const node=e.target.closest('[data-action]');if(!node)return;if(node.classList.contains('overlay')&&e.target!==node)return;e.preventDefault();takeAction(node.dataset.action)});
ROOT.addEventListener('change',e=>{const el=e.target;const id=el.id;if(id==='pick-micro'){ui.focusMicro=el.value;ui.group=el.value==='all'?'all':P(el.value)?.groupId||'all';ui.page=0}else if(id==='pick-drug'){ui.focusDrug=el.value;ui.page=0}else if(id==='pick-view'){ui.mapStyle=el.value;ui.page=0}else if(id==='filter-group'){ui.group=el.value;ui.focusMicro='all';ui.page=0}else if(id==='filter-family'){ui.drugFamily=el.value;ui.page=0}else if(id==='filter-status'){ui.status=el.value;ui.page=0}else if(id==='filter-sort'){ui.order=el.value;ui.page=0}else if(id==='only-known'){ui.onlyKnown=el.checked;ui.page=0}else if(id==='catalog-family'){ui.drugFamily=el.value;ui.drug=D.antibiotics.find(a=>el.value==='all'||a.family===el.value)?.id;ui.drugQuery=''}else if(id==='micro-group'){ui.microGroup=el.value;ui.micro=D.pathogens.find(p=>el.value==='all'||p.groupId===el.value)?.id;ui.microQuery=''}else if(id==='syndrome-site'){ui.syndromeSite=el.value;ui.syndrome=D.syndromes.find(s=>el.value==='all'||s.site===el.value)?.id}else if(id==='compare-group'){ui.compareGroup=el.value}else if(id==='lab-micro'){ui.labMicro=el.value}else if(id==='lab-syndrome'){ui.labSyndrome=el.value;ui.labStep=0}else if(id==='add-compare'){if(el.value&&!ui.compare.includes(el.value)&&ui.compare.length<4)ui.compare.push(el.value)}else if(el.dataset.color){pal[el.dataset.color]=el.value;storage.set('atb_palette_v9',pal)}render()});
ROOT.addEventListener('input',e=>{const el=e.target;if(el.id==='global-query'){ui.command=el.value;const list=ROOT.querySelector('#global-results');if(list)list.innerHTML=globalResultMarkup(el.value);return}if(el.id==='lab-search'){ui.labQuery=el.value;const target=ROOT.querySelector('#lab-candidates');if(target)target.innerHTML=labDrugOptions().filter(a=>N(a.name+' '+a.family).includes(N(ui.labQuery))).slice(0,10).map(labCandidate).join('');return}if(el.dataset.color){pal[el.dataset.color]=el.value;storage.set('atb_palette_v9',pal);el.closest('label')?.style.setProperty('--taxon',el.value);const hex=document.getElementById('hex-'+el.dataset.color);if(hex)hex.textContent=el.value;return}if(el.id==='drug-search'||el.id==='micro-search'){const start=el.selectionStart;const val=el.value;const isDrug=el.id==='drug-search';ui[isDrug?'drugQuery':'microQuery']=val;render();const field=document.getElementById(el.id);field?.focus();try{field?.setSelectionRange(start,start)}catch{}}});

// Native drag-and-drop works with pointer input; adjacent arrow controls remain keyboard-accessible.
ROOT.addEventListener('dragstart',e=>{const item=e.target.closest('[data-draggable]');if(!item)return;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',item.dataset.draggable);item.classList.add('is-dragging')});
ROOT.addEventListener('dragend',e=>{e.target.closest('[data-draggable]')?.classList.remove('is-dragging');ROOT.querySelectorAll('.lab-dropzone,.lab-picked').forEach(x=>x.classList.remove('drop-active'))});
ROOT.addEventListener('dragover',e=>{const t=e.target.closest('#lab-dropzone,.lab-picked');if(!t)return;e.preventDefault();e.dataTransfer.dropEffect='move';t.classList.add('drop-active')});
ROOT.addEventListener('dragleave',e=>{if(!e.relatedTarget?.closest?.('#lab-dropzone,.lab-picked'))e.target.closest('#lab-dropzone,.lab-picked')?.classList.remove('drop-active')});
ROOT.addEventListener('drop',e=>{const zone=e.target.closest('#lab-dropzone');if(!zone)return;e.preventDefault();const drug=e.dataTransfer.getData('text/plain');if(!A(drug))return;const at=e.target.closest('.lab-picked')?.dataset.draggable;const i=ui.labDrugs.indexOf(drug);if(i!==-1)ui.labDrugs.splice(i,1);if(ui.labDrugs.length>=4){return render()}const position=at?ui.labDrugs.indexOf(at):-1;if(position>=0)ui.labDrugs.splice(position,0,drug);else ui.labDrugs.push(drug);render()});
window.addEventListener('hashchange',()=>{ui.drawer=null;ui.modal=null;ui.mobileNav=false;restoreHash();render();window.scrollTo(0,0)});
window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();takeAction('search')}if(e.key==='Escape'&&(ui.modal||ui.drawer||ui.mobileNav)){ui.modal=null;ui.drawer=null;ui.mobileNav=false;render()}});
async function boot(){try{const [a,b]=await Promise.all([fetch('./data/atlas.json'),fetch('./data/insights.json')]);if(!a.ok||!b.ok)throw Error('No fue posible cargar los archivos JSON.');D=await a.json();X=await b.json();for(const r of D.relations){relMap.set(r.antibiotic+'|'+r.pathogen,r);byDrug.set(r.antibiotic,[...(byDrug.get(r.antibiotic)||[]),r]);byMicro.set(r.pathogen,[...(byMicro.get(r.pathogen)||[]),r])}const saved=storage.get('atb_palette_v9')||storage.get('atb_palette_v7')||{};pal=Object.fromEntries(D.groups.map((g,i)=>[g.id,/^#[0-9a-fA-F]{6}$/.test(saved[g.id]||'')?saved[g.id]:PALETTES.prisma[i%12]]));ui.viewSaved=storage.get('atb_v9_views')||[];restoreHash();if(!location.hash){try{history.replaceState(null,'',location.pathname+location.search+'#/mapa')}catch{}}ui.route=route();render()}catch(err){ROOT.innerHTML=`<div class="loading"><h2>No se pudo cargar ATB Atlas</h2><p>${H(err.message)}</p></div>`;console.error(err)}}
boot();